insert into public.quote_acceptances (estimate_id, revision, quote_link_id, accepted_name, accepted_title, accepted_email, signature_text, agreed_to_terms, terms_version_id, total_cents, ip, user_agent)
  select e.id, 1, (select id from public.quote_links where estimate_id = e.id order by created_at desc limit 1), 'Sample Signer', 'Registrar', 'signer@example.com', 'Sample Signer', true,
         (select id from public.terms_versions where is_current), e.total_cents, '127.0.0.1', 'seed'
  from public.estimates e where e.id = (select id from seed_est where k = 'est_10');
update public.estimates set accepted_at = now() - interval '1 day' where id = (select id from seed_est where k = 'est_10');
